//! Integration tests of the virtual folder "Everything" (`ui.md`):
//! `list_everything` reads whole threads from `thread` instead of merging
//! every folder (`list_threads_in`), and must list the same threads, in the
//! same order, shown in the same folder with the same counters, page after
//! page.
//!
//! The mailbox is generated by `seed` (deterministic): several thousand
//! threads spread over every workflow folder, with flags, attachments,
//! replies and unread mail.

use nm_api::{ThreadFilter, ThreadSort, ThreadSummary};
use nm_store::Store;
use nm_store::seed::{SeedOptions, seed};

/// A seeded store and the ids of every folder. Every seventh thread is
/// tagged "Clients", and the group "Équipe" (id 1) holds the senders of
/// three threads.
fn store() -> (Store, Vec<i64>) {
    let mut store = Store::open_in_memory().unwrap();
    seed(&mut store, &SeedOptions { threads: 1500, seed: 7, now: 1_750_000_000 }).unwrap();
    let threads: Vec<i64> = store.conn().prepare("SELECT id FROM thread ORDER BY id").unwrap()
        .query_map([], |r| r.get(0)).unwrap().map(|r| r.unwrap()).collect();
    for t in threads.iter().step_by(7) {
        store.tag_thread(*t, "Clients", false, nm_core::Source::App).unwrap();
    }
    for t in [threads[3], threads[300], threads[900]] {
        // A thread without a received mail has no sender to add: skip it.
        let _ = store.set_group_member("Équipe", None, Some(t), false, nm_core::Source::App);
    }
    let folders = store.list_folders().unwrap().iter().map(|f| f.id).collect();
    (store, folders)
}

/// Every page of a list, read `page` threads at a time.
fn all_pages(mut next: impl FnMut(Option<&str>) -> (Vec<ThreadSummary>, Option<String>)) -> Vec<ThreadSummary> {
    let mut out = Vec::new();
    let mut cursor: Option<String> = None;
    loop {
        let (items, c) = next(cursor.as_deref());
        out.extend(items);
        match c {
            Some(c) => cursor = Some(c),
            None => return out,
        }
    }
}

/// What a list row shows, compared between the two ways of listing.
fn rows(items: &[ThreadSummary]) -> Vec<(i64, i64, i64, i64, i64, i64)> {
    items.iter().map(|t| (t.id, t.folder_id, t.date_last_received, t.date_last_modified, t.message_count, t.unread_count)).collect()
}

/// The address with the most mails, for the contact criterion.
fn busiest_address(store: &Store) -> i64 {
    store
        .conn()
        .query_row("SELECT address_id FROM message_address GROUP BY address_id ORDER BY count(*) DESC LIMIT 1", [], |r| r.get(0))
        .unwrap()
}

/// The filters compared. Not `seen`: see
/// `unread_in_everything_looks_at_the_whole_thread`.
fn filters(contact: i64) -> Vec<ThreadFilter> {
    vec![
        ThreadFilter::default(),
        ThreadFilter { flagged: Some(true), ..Default::default() },
        ThreadFilter { flagged: Some(false), ..Default::default() },
        ThreadFilter { attachments: Some(true), ..Default::default() },
        ThreadFilter { answered: Some(true), ..Default::default() },
        ThreadFilter { conversation: Some(true), ..Default::default() },
        ThreadFilter { from: vec!["@gmail.com".into()], ..Default::default() },
        ThreadFilter { not_from: vec!["@gmail.com".into()], ..Default::default() },
        ThreadFilter { to: vec!["alex".into()], ..Default::default() },
        ThreadFilter { contains: Some("facture".into()), ..Default::default() },
        ThreadFilter { after: Some(1_740_000_000), before: Some(1_745_000_000), ..Default::default() },
        ThreadFilter { tag: Some("clients".into()), ..Default::default() },
        ThreadFilter { group_id: Some(1), ..Default::default() },
        ThreadFilter { address_id: Some(contact), ..Default::default() },
        // A criterion of a tag list combined with attributes.
        ThreadFilter { tag: Some("Clients".into()), attachments: Some(true), ..Default::default() },
        ThreadFilter { address_id: Some(contact), flagged: Some(false), from: vec!["@gmail.com".into()], ..Default::default() },
    ]
}

#[test]
fn everything_lists_what_every_folder_lists_page_after_page() {
    let (store, folders) = store();
    let accounts: Vec<i64> = {
        let mut a: Vec<i64> = store.list_folders().unwrap().iter().map(|f| f.account_id).collect();
        a.dedup();
        a
    };
    let contact = busiest_address(&store);
    for filter in filters(contact) {
        for sort in [ThreadSort::Received, ThreadSort::Modified] {
            let merged = all_pages(|c| store.list_threads_in(&folders, c, 37, sort, &filter).unwrap());
            let everything = all_pages(|c| store.list_everything(None, c, 37, sort, &filter).unwrap());
            assert!(!merged.is_empty() || filter != ThreadFilter::default());
            assert_eq!(rows(&everything), rows(&merged), "{filter:?} {sort:?}");
            // The scope of one account gives the same, the seed having one.
            let one = all_pages(|c| store.list_everything(Some(accounts[0]), c, 37, sort, &filter).unwrap());
            assert_eq!(rows(&one), rows(&merged), "account {filter:?} {sort:?}");
        }
    }
    // Another account sees nothing of this one.
    let (none, next) = store.list_everything(Some(9999), None, 50, ThreadSort::Received, &ThreadFilter::default()).unwrap();
    assert!(none.is_empty() && next.is_none());
}

#[test]
fn unread_in_everything_looks_at_the_whole_thread() {
    // A thread with an unread mail in one folder, but whose latest mail is
    // read and in another folder (the Inbox mail, then the user's reply in
    // Sent, say). Listed folder by folder, the thread was shown in the
    // folder of its latest mail, where nothing is unread, and its unread
    // row was skipped as not the latest: it vanished from "unread".
    let (mut store, _) = store();
    // A thread of the seed in two folders or more, made read everywhere,
    // then one mail of an older folder made unread again (the counters are
    // updated as `refresh_thread` would).
    let (thread, older): (i64, i64) = store
        .conn()
        .query_row(
            "SELECT tf.thread_id, tf.folder_id FROM thread_folder tf
              WHERE EXISTS (SELECT 1 FROM thread_folder o WHERE o.thread_id = tf.thread_id
                             AND o.date_last_received > tf.date_last_received)
              LIMIT 1",
            [],
            |r| Ok((r.get(0)?, r.get(1)?)),
        )
        .expect("the seed has threads in several folders");
    store.set_thread_seen(thread, true, nm_core::Source::Cli).unwrap();
    store
        .conn()
        .execute_batch(&format!(
            "UPDATE message SET is_seen = 0 WHERE id = (SELECT id FROM message WHERE thread_id = {thread} AND folder_id = {older} LIMIT 1);
             UPDATE thread_folder SET unread_count = 1 WHERE thread_id = {thread} AND folder_id = {older};
             UPDATE thread SET unread_count = 1 WHERE id = {thread};"
        ))
        .unwrap();
    let unread = ThreadFilter { seen: Some(false), ..Default::default() };
    let everything = all_pages(|c| store.list_everything(None, c, 100, ThreadSort::Received, &unread).unwrap());
    assert!(everything.iter().any(|t| t.id == thread));
    // And "read" leaves it out: it has an unread mail.
    let read = ThreadFilter { seen: Some(true), ..Default::default() };
    let everything = all_pages(|c| store.list_everything(None, c, 100, ThreadSort::Received, &read).unwrap());
    assert!(!everything.iter().any(|t| t.id == thread));
}

#[test]
fn a_cursor_of_everything_continues_where_the_page_stopped() {
    let (store, _) = store();
    let filter = ThreadFilter::default();
    let (first, cursor) = store.list_everything(None, None, 10, ThreadSort::Received, &filter).unwrap();
    let (second, _) = store.list_everything(None, cursor.as_deref(), 10, ThreadSort::Received, &filter).unwrap();
    let (both, _) = store.list_everything(None, None, 20, ThreadSort::Received, &filter).unwrap();
    assert_eq!(rows(&[first, second].concat()), rows(&both));
    // A malformed cursor is refused.
    assert!(store.list_everything(None, Some("x"), 10, ThreadSort::Received, &filter).is_err());
}

#[test]
fn the_lists_of_a_tag_a_group_and_a_contact_are_complete_and_ordered() {
    let (store, _) = store();
    let contact = busiest_address(&store);
    for filter in [
        ThreadFilter { tag: Some("Clients".into()), ..Default::default() },
        ThreadFilter { group_id: Some(1), ..Default::default() },
        ThreadFilter { address_id: Some(contact), ..Default::default() },
    ] {
        let list = all_pages(|c| store.list_everything(None, c, 25, ThreadSort::Received, &filter).unwrap());
        // Newest first on the date shown, every page (no cap at 200).
        assert!(list.windows(2).all(|w| (w[0].date_last_received, w[0].id) >= (w[1].date_last_received, w[1].id)), "{filter:?}");
        let ids: std::collections::BTreeSet<i64> = list.iter().map(|t| t.id).collect();
        assert_eq!(ids.len(), list.len(), "{filter:?}: a thread twice");
        assert!(!list.is_empty(), "{filter:?}");
    }
    // The tag: exactly the tagged threads (every seventh), more than a page.
    let tagged = all_pages(|c| {
        store.list_everything(None, c, 25, ThreadSort::Received, &ThreadFilter { tag: Some("CLIENTS".into()), ..Default::default() }).unwrap()
    });
    let expected: i64 = store.conn().query_row(
        "SELECT count(DISTINCT m.thread_id) FROM message_keyword mk JOIN message m ON m.id = mk.message_id WHERE mk.keyword = 'Clients'",
        [], |r| r.get(0)).unwrap();
    assert_eq!(tagged.len() as i64, expected);
    assert!(expected > 200);
}

// ---------------------------------------------------------------------------
// All Mail (`ui.md`, "Sélecteur d'attributs"): every folder but Deleted,
// Junk and Banned. Read in one walk of the date index of `thread_folder`;
// it must list exactly what the folders of All Mail list together.
// ---------------------------------------------------------------------------

/// The folders of All Mail: all but Deleted, Junk and Banned.
fn all_mail_folders(store: &Store) -> Vec<i64> {
    store
        .list_folders()
        .unwrap()
        .iter()
        .filter(|f| !f.role.is_some_and(|r| nm_core::FolderRole::OUT_OF_ALL_MAIL.contains(&r)))
        .map(|f| f.id)
        .collect()
}

#[test]
fn all_mail_lists_what_its_folders_list_page_after_page() {
    let (store, _) = store();
    let folders = all_mail_folders(&store);
    let contact = busiest_address(&store);
    let mut seen_rejected = false;
    for filter in filters(contact) {
        for sort in [ThreadSort::Received, ThreadSort::Modified] {
            let merged = all_pages(|c| store.list_threads_in(&folders, c, 37, sort, &filter).unwrap());
            let all_mail = all_pages(|c| store.list_all_mail(None, c, 37, sort, &filter).unwrap());
            assert_eq!(rows(&all_mail), rows(&merged), "{filter:?} {sort:?}");
            let account = store.list_folders().unwrap()[0].account_id;
            let one = all_pages(|c| store.list_all_mail(Some(account), c, 37, sort, &filter).unwrap());
            assert_eq!(rows(&one), rows(&merged), "account {filter:?} {sort:?}");
            if filter == ThreadFilter::default() {
                // Fewer threads than Everything: the seed fills Deleted,
                // Junk and Banned too.
                let everything = all_pages(|c| store.list_everything(None, c, 37, sort, &filter).unwrap());
                seen_rejected |= everything.len() > all_mail.len();
            }
        }
    }
    assert!(seen_rejected, "the seed should have threads only in Deleted, Junk or Banned");
    let (none, next) = store.list_all_mail(Some(9999), None, 50, ThreadSort::Received, &ThreadFilter::default()).unwrap();
    assert!(none.is_empty() && next.is_none());
}

/// A thread whose latest mail was deleted keeps its place in All Mail:
/// sorted and shown by its latest mail left, where Everything puts it at
/// the date of the mail deleted.
#[test]
fn a_mail_deleted_does_not_move_its_thread_in_all_mail() {
    let (store, _) = store();
    let thread: i64 = store
        .conn()
        .query_row(
            "SELECT tf.thread_id FROM thread_folder tf JOIN folder f ON f.id = tf.folder_id
              WHERE f.role NOT IN ('deleted', 'junk', 'banned') ORDER BY tf.thread_id LIMIT 1",
            [],
            |r| r.get(0),
        )
        .unwrap();
    let deleted: i64 = store.conn().query_row("SELECT id FROM folder WHERE role = 'deleted'", [], |r| r.get(0)).unwrap();
    // Its latest mail is now in Deleted, the most recent of the box (the
    // aggregates set as `refresh_thread` would).
    store
        .conn()
        .execute_batch(&format!(
            "DELETE FROM thread_folder WHERE thread_id = {thread} AND folder_id = {deleted};
             INSERT INTO thread_folder (thread_id, folder_id, date_last_received, date_last_modified, message_count, unread_count)
                  VALUES ({thread}, {deleted}, 1900000000, 1900000000, 1, 0);
             UPDATE thread SET date_last_received = 1900000000, date_last_modified = 1900000000 WHERE id = {thread};"
        ))
        .unwrap();
    let everything = store.list_everything(None, None, 5, ThreadSort::Received, &ThreadFilter::default()).unwrap().0;
    assert_eq!(everything[0].id, thread, "Everything puts it first");
    let all_mail = all_pages(|c| store.list_all_mail(None, c, 50, ThreadSort::Received, &ThreadFilter::default()).unwrap());
    let i = all_mail.iter().position(|t| t.id == thread).expect("still in All Mail");
    assert!(all_mail[i].date_last_received < 1900000000);
    assert_ne!(all_mail[i].folder_id, deleted);
    assert!(i == 0 || all_mail[i - 1].date_last_received >= all_mail[i].date_last_received);
}
